def split_csv(line):
    """Parse one line of CSV and return its fields as a list of strings.

    Returns None if the line is malformed.
    """
    if line == "":
        return [""]

    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line):
                            if line[i] != ',':
                                return None
                            i += 1
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                # Skip the comma
                i += 1

    return fields

